P["MP-017"] = ("下届香港特首由女性出任：2017年3月26日选举委员会投票，林郑月娥一系当选，男性候选人陪跑。置信中高，分层：方向层女性胜出，具体层点名女性政务司长出身者。应期以月为单位，2017年3月投票日见分晓。", "卡面未标注 tradition 字段，按题面体裁自决：时局人物气色与选情结构合参（MP-017 问男女之别、时点在2016年12月林郑改口考虑参选之际）。\n梁振英已宣布不连任，女性高官中只有政务司长改口备选且获建制与中央信任通道，男性财政司长辞职备选但缺乏选举委员会过半票源结构；气色与票源双指女性。应期合通则(a)(k)：选举为定日事件，日档由投票日2017-03-26定点。", 0.72)
P["MP-018"] = ("曾俊华不能当选2017年香港行政长官：民望最高但选举委员会票源不足，2017年3月26日投票落败，得票明显低于当选门槛与对手。置信高。应期：2017年3月投票日为终局点，无后段翻盘。", "卡面未标注 tradition 字段，按题面体裁自决：面相气色与选制结构合参（MP-018 对象为1951年生前财政司长、民望最高而传媒指对手获北京支持）。\n小圈子选举决胜在选委结构而非民望；其相格主清贵名望、主民望而不主实权票仓，名与位分离。等级校准(b)：只断落选不断其票数垫底，保留得票第二的量级。", 0.8)
P["MP-019"] = ("2017年香港特首选举花落林郑月娥：3月26日投票以高票当选，曾俊华第二、胡国兴第三且票数最低。置信高。应期单点：2017年3月26日。", "卡面未标注 tradition 字段，按题面体裁自决：三候选人生年干支与选情结构合参（MP-019 林郑1957酉年、曾1951卯年、胡1946酉年，写作于选前一日）。\n酉年金鸡之象与丁酉流年同气，林郑得年运同气与中央支持双重加持；曾卯酉相冲主冲而难成，胡年高而票源最薄。三人排序由此定。", 0.82)
P["OC-001"] = ("吴佩孚一生事业先盛后衰：早中年以武功权位显赫、主政一方为巅峰，晚年下野后困顿、名位尽失，终局潦倒而终。运档：青年至中年火土运助势为上升段，晚年水木运克泄为衰败段，晚景以年月档断、衰象集中在最后一步运。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平（OC-001 四柱甲戌 戊辰 戊申 壬子，日主戊土）。\n戊土生辰月得令，财官印俱透而身旺任事，主早年权位；时柱壬子财坐子水冲动晚景根基，晚运逢水旺克土、财来坏印，主下野后困顿。格局强度足级断盛衰两段，合通则(i)(j)逐段指认：上升段据月令得气，衰段据时柱与晚运冲克。", 0.7)
P["OC-002"] = ("宋子文一生贵显极高：居财政金融顶层、富贵双全，行运中年最盛，晚年退居海外而保尊荣，无牢狱破败之终局。运档以年档：壮年水金运财官相生为巅峰，晚年运平而守成。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平（OC-002 四柱甲午 乙亥 庚申 己卯，原书取庚申日）。\n庚金生亥月伤官生财，乙庚合财、坐申得禄，财官印链条完整，主银行世家而掌财政；身得禄根不弱，能任大财大官，故按足级断顶层贵显。晚年无冲破日主之凶运象，断守成善终。", 0.72)
P["OC-003"] = ("虞洽卿一生名位与财运俱盛：商界领袖级大富，晚年名望不坠、安享高寿善终。运档：中年后金水运生财为持续上升，晚年运不见破格，富贵以年月档收束于高位。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平（OC-003 四柱丁卯 丙午 庚午 己卯）。\n庚金生午月官杀重而己土印透化杀生身，杀印相生主名位；卯木财星两见生杀旺势，主商场聚财。官杀虽重而有印通关，不作压制降格，足级断商界领袖与晚年安荣。", 0.7)
P["OC-004"] = ("颜惠庆仕途贵显而平顺：外交内阁级高位，行运无大破败，晚年退隐安稳、善终。运档：中年木火运官印相生为仕途上升段，晚年运平守成，年档表达。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平（OC-004 四柱丁丑 癸卯 乙巳 丙子）。\n乙木生卯月得禄，癸水印透、丙丁食伤吐秀，木火通明而印护身，主文才外交之贵；子卯刑只主小波折不破格，降格无据故按外交高官足级断，晚年安稳。", 0.68)
P["OC-005"] = ("吴经熊前程贵显：法学界与司法界顶层人物，学术名望与官位并得，一生顺遂多于挫折，晚年安荣。运档：中年运助印比为上升，晚年守成，年档。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平（OC-005 四柱己亥 丁卯 乙未 己卯）。\n乙木生卯月建禄，两卯一亥根气深厚，丁火食神透出吐秀、己土财星有制，主学问成名而得位；身旺有秀有财，格局清纯，足级断法院院长级贵显与学术声名。", 0.7)
P["OC-006"] = ("荣宗敬当前危机可渡而事业根基不保全盛：1935年前后挫折为近段低点，企业经收缩整顿后能存续一段，但往后再无早年扩张之势，晚年家业渐衰、本人于数年内（年月档，约1938年前后）走到终局。近段：乙亥年后一二年内止跌；远段：运入衰地，规模收缩。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平（OC-006 四柱癸酉 庚申 戊午 甲寅，问于约1935年企业危机时）。\n戊土生申月食神生财，财源本巨；甲寅七杀时柱与寅申冲动根基，危机年运冲提纲主大挫。合通则(i)：近段据食伤生财链未断断可渡，远段据时柱冲与运衰断收缩，翻转触发为寅申冲指向根基动摇。", 0.62)
P["OC-007"] = ("袁寒云性情风流狂放、才高而命薄：文名极盛而仕途无成，富贵不能久享，寿数不长，约四十岁出头（1931年辛未年前后，年档）为终局，一生际遇以早逝收束。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平（OC-007 四柱庚寅 甲申 甲申 甲戌，问于1931年命主新逝后验断）。\n甲木生申月七杀当令，两申冲寅、杀重身危，甲木时干比助只成狂放才气不能成格局救应；杀攻身而无印化、无食制，等级按无救弱级断：文名足、寿数亏。应验对象为命主本人，合(f)复核。", 0.66)
P["OC-008"] = ("商震行运稳进、权位可达省级军政高位并守得住：中年后运程向上，晚年退居而安，无骤败。运档年档：酉金得气之运为权位上升段。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平（OC-008 四柱戊子 辛酉 乙未 己卯，原书取己卯时）。\n乙木生酉月七杀，辛金透杀而戊己财生杀、未卯半合木局扶身，杀有制化倾向且身有根，主军政历练而成省主席级；卯酉冲主一生迁动多而不主破败，足级断高位可守。", 0.64)
P["OC-009"] = ("顾维钧财富仕途俱佳、婚姻多波折：外交顶层长青，仕途跨度极长且晚年尊荣；婚姻方面有再娶/聚少离多之象。运档年档：中晚年运不破格，仕途长青，婚姻波折集中在中年运段。注：卡面四柱转录残缺，置信下调。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平（OC-009 对象顾维钧；卡面 birth.pillars 仅写『原书应运篇下论造、四柱以原书为准、转录本个别字待校』，四柱残损未给全）。\n输入残损照实注明：无完整四柱不能逐字推运，只能据命主已历任使节内阁的事实层与外交官造常见官印结构作方向断，故降置信，不臆补四柱。方向：官印相生型长青、妻宫多动主婚姻波折。", 0.45)
P["OC-010"] = ("溥仪一生际遇大起大落、帝位虚名而实运坎坷：少年退位、中年有复辟与傀儡之段、后段囚居改造，晚年以平民作家身份平静终老，寿约六十余（年月档，终局在1960年代后段）。全程无实权重掌之运。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平（OC-010 四柱丙午 庚寅 壬午 丙午，原书未附大运表）。\n壬水生寅月食神生财，三午财星极旺而身弱无根，财多身弱担不起江山之财，主有位无实、受人摆布；庚金印透为后段庇护之象，主晚年得制度安置而平民终老。大运表缺失，应期只到年月档不落日。", 0.68)
