P["OC-011"] = ("阮玲玉性情敏感重情、一生结局凶险早折：影名极盛而感情与舆论压力致命，寿数短，约二十五岁上下（1935年，年档）自尽式终局。断语等级按不治/早折级，因格局无救。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平（OC-011 四柱庚戌 辛巳 己亥 乙亥，问于1935年命主新逝后）。\n己土生巳月印旺，亥水财星两见冲巳、乙木七杀透时，财杀交攻而印被冲动，情志与名声压力无出口；巳亥冲为关键压制依据，足据降至早折级。应验对象命主本人，合(f)。", 0.66)
P["OC-012"] = ("杨秀琼成名极早而婚姻与后运不佳：少女泳坛成名为巅峰，其后名声渐退，婚姻有为妾/受制于权贵之象，晚年行运平淡困顿，与早年盛名落差大。运档：五岁起运己巳庚午为成名段，辛未壬申后财官混杂主婚姻波折，癸酉甲戌晚段平衰。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平（OC-012 四柱己未 戊辰 丁未 戊申，卡面附大运己巳起六步）。\n丁火生辰月伤官重，戊己伤官叠透主早慧出名而傲上招忌；申金财星为后运所向，伤官见财又逢官运混杂，主婚姻受权势牵制。逐段核(j)：成名段据伤官吐秀，衰段据晚运无印护身。", 0.62)
P["OC-013"] = ("周信芳一生艺术盛名长久、晚年行运凶险：舞台地位宗师级，晚年逢运冲克有政治风波与病困，终局不宁（年月档，晚年最后一步运为险段）。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平（OC-013 四柱甲午 丁丑 辛酉 甲午，八岁起运）。\n辛金坐酉禄旺，丁火官星透而两午冲动，主以技艺得官名；身旺任官主宗师地位。晚运若逢水木冲禄与官星受损，主风波病困——远段触发指认为禄根受冲，故晚年按险级断而非守成。", 0.6)
P["OC-014"] = ("蒋邦彦仕途可至财政厅长级而行运有起伏：中年得位，后运财杀交攻有罢黜/破财之段，晚年平淡。运档年档：卯木官旺之运升，丑运财库冲动主退。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平（OC-014 四柱庚辰 己卯 壬寅 辛丑）。\n壬水生卯月伤官，寅卯木旺生势、庚辛印透救身，伤官佩印主财政才干而得厅长级；时柱辛丑与卯木相战、辰丑土重压水，后运主退位破财。等级足级到厅长、不拔至部级，压制据印根不厚。", 0.6)
P["OC-015"] = ("乔治五世一生际遇为君主尊荣、稳坐王位至终：中年经历大战而王室存续，晚年病终在位（年月档，终局1930年代中段），无退位之变。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平（OC-015 四柱乙丑 辛巳 甲辰 甲子，韦氏据西报生庚演造）。\n甲木生巳月食神生财，辛金正官透合、子水印护，官印食链条顺，主守成君主之贵；辰丑土为财库主国库之象。身中和偏弱而官印有情，足级断在位善终、不主大开创。", 0.58)
P["OC-016"] = ("韦千里一生以命学立身、事业中上而非大富大贵：职业命师名望可成，晚年运平、衣食无缺而权位无份，际遇以术数终老。运档年档：卯木运为名望段，晚运金水平守。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平（OC-016 四柱辛亥 辛卯 庚子 庚辰，命师自论）。\n庚金生卯月财旺，子水伤官生财、两辛两庚比劫争财，主靠技艺口才谋生而财难大聚；无官星显位，主无仕途。格局中平，等级校准(b)按中上立身断，不拔高为巨富高官。", 0.62)
P["OC-017"] = ("刘澄如一生大富：丝商巨富级，财可敌一地之商，贵气次于富气，晚年守富安终。运档年档：酉金运财星得地为聚富主段。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平用神成败救应（OC-017 四柱壬戌 己酉 丁丑 甲辰，《子平真诠评注》引例）。\n丁火生酉月财当令，己土食神生财、丑辰戌土局泄秀生金，财格成而有食神救应流通，主经商巨富；甲木印透只作名望之辅，富大于贵，足级断巨富。", 0.7)
P["OC-018"] = ("史量才一生地位极高而晚年行运大凶：报业巨头地位足级，晚年逢险年有横祸/遇害之虞，终局不善（年月档，险象集中在晚年运与流年冲克之年，约1930年代中段）。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平用神成败救应（OC-018 四柱己卯 丙子 庚寅 辛巳）。\n庚金生子月伤官，丙火七杀透、寅巳刑动，伤官见官又逢杀，主言论锋芒招祸；早运助财官成报业地位，晚运冲提纲与杀星得地为翻转触发，远段按横祸级断。应验对象命主本人。", 0.64)
P["OC-019"] = ("杨杏佛行运险年显著、一生有横祸早折之险：学术行政地位可成，但中年险年（年月档，约1933年前后）为生死关，终局主遇害/横夭而非善终。注：两书四柱全异，本例以卡面徐乐吾书造为准，置信下调。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平用神成败救应（OC-019 卡面四柱癸巳 丙辰 壬申 癸卯，并注明韦书另载全异造、本例以徐书为准）。\n壬水坐申得生，丙火财透、巳火冲动，财杀与劫财癸水并见，主活动家锋芒与政争之险；巳申合刑指向险年。输入有异造分歧，照实注明并降置信，不并用两造。", 0.55)
P["OC-020"] = ("谭延闿贵显极高、可达政府主席级，行运险年在中晚年：权位足级登顶，险年主病终在任（年月档，约1930年前后为终局点），无牢狱贬谪之败。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平用神成败救应（OC-020 四柱己卯 丁丑 癸丑 乙卯）。\n癸水生丑月七杀，丁火财生杀、乙卯食神制杀，杀有制而财辅，主文武兼资登主席级；两丑两卯土木相战、身弱杀重，险年据杀重运年引动断病终在任。等级足级与险级并写，压制据身弱无强印。", 0.64)
# ---- segment 3: OC-021..030 ----
P["OC-021"] = ("陆荣廷格局中上、一生贵显可达一方军阀首领级：武贵足级，早中年拥兵据地为巅峰，晚年势力消退、退居终老，无再起之运。运档年档：酉金杀旺运主拥兵，晚运衰主退场。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平格局高低（OC-021 四柱戊午 辛酉 乙卯 丙戌）。\n乙木生酉月七杀，坐卯禄、丙火伤官制杀、戊土财辅，杀有制而身有禄，主绿林/行伍起家成一方首领；戌酉害与午戌火局主晚年火土燥烈耗木，远段退场据此。足级断军阀首领、不拔至 central 政权级。", 0.66)
P["OC-022"] = ("袁树珊科第无成、学业以命学立身：一生屡试不第，不走仕途正轨，终以命理著述与术数名家身份立身，晚年以学问名望终老。运档年档：酉金官旺少年运主应试而屡挫，寅木运后转术数立身。", "卡面未标注 tradition 字段，按题面体裁自决：八字子平自造自批（OC-022 四柱辛巳 丁酉 乙巳 戊寅，大运丙申起，安命甲午）。\n乙木生酉月七杀两巳冲动，丁火食神制杀而官星被冲，主功名门前反复受阻；戊土财透、寅木禄根在时，主晚年靠实学谋生立名。卡面自述屡试不第与盘象合参，合(e)事实优先。", 0.68)
P["OC-023"] = ("钟下所覆之物为一件已破损的圆形器物：属土瓦/瓷石之类（鼎器之象），不完好——有裂纹或缺口。事件级断语：物品为圆腹有足之器、破损不全；无应期可言（即时射覆）。", "卡面未标注 tradition 字段，按题面体裁自决：梅花易数射覆（OC-023 卡面附卦象『火风鼎 变 雷风恒』）。\n鼎卦主三足圆器、烹饪之器，离火巽木生之，象为陶瓦火烧之器；变恒而互见兑巽，兑主毁折缺口，故断破损不完好。合(g)密度：落到物品（圆器）与状态（有裂缺）两项。完好与否一问明确答：不完好。", 0.5)
P["OC-024"] = ("葬事有着落、预言应验：易者身后无资之困可解，资从地下/窖藏之处得——枕下或窖中藏有金银（击鼠得金之象），足以营葬。应期以日档：来访后数日内掘得见金。", "卡面未标注 tradition 字段，按题面体裁自决：梅花易数序文成例体裁（OC-024 邵雍携遗书访易者之家、其家无资营葬）。\n遗书预托与鼠扰枕边之象合：鼠主窖藏、枕下藏物，土中金为经典取象；象落具体物品（窖藏金银）与数量级（足资一葬），合(c)(g)。应验对象为易者身后葬事，非来访者本人，合(f)。", 0.55)
P["OC-025"] = ("椅底预书应验：届预书所定年月日，椅子将被坐破，预言如期成真。应期以日档：即预书所载之日，事件单点、无两段。", "卡面未标注 tradition 字段，按题面体裁自决：梅花易数序文预言体裁（OC-025 邵雍预书某年月日椅将被坐破于椅底）。\n本题只问预言是否应验，属单点事项，通则(i)明写不适用两段式。预书者以象数定日、椅为木器受人压坐而破，象与期自洽，断如期应验；置信中，因卡面未给起卦细节、只据序文体裁。", 0.52)
P["OC-026"] = ("今年功名可成而不同步：两客中一人当年得功名/中式，另一人落榜或迟一年。课象主成多于败，具体为长者先成、幼者后成之象。应期以年档：1643年当年放榜见分晓。", "卡面未标注 tradition 字段，按题面体裁自决：大六壬（OC-026 课式涉害/曲直，三传乙未青龙、己亥螣蛇、癸卯玄武，甲午旬辰巳空）。\n三传未亥卯三合木局成曲直格，木主文书功名、青龙初传主喜庆得位，故功名有成；中传螣蛇主虚惊纠缠、末传玄武主暗昧落空，一成一滞之象落到两人不同步。盘面不全（无四课天盘全图），守六壬第八节只据三传课格作断。", 0.55)
P["OC-027"] = ("此行不得意：奉诏北上凶多吉少，本人身体有损/行程受阻，老母在家亦有不安之象。近段：入京途中即遇阻滞；远段：难以全身而退，职位难保。应期以月档：1642年冬至次年初数月内见凶。", "卡面未标注 tradition 字段，按题面体裁自决：大六壬（OC-027 课式无禄/无路，三传癸酉六合、戊辰太阴、亥青龙空，甲子旬戌亥空）。\n课名无禄无路已主前路断绝；末传亥水青龙落空，主归路与庇护皆空；辰酉合而中传太阴主暗耗。母安一问：年命与宅象受空亡牵动断不安。合(i)两段：近段阻滞、远段难退，触发为末传空亡。盘面不全守第八节。", 0.6)
P["OC-028"] = ("入觐考选可得官而品级中下：得一实缺文官（州县/佐贰一类），非馆阁清要之职；授官在考选后数月内（月档，1631年上半年）。过程有口舌文书周折而终成。", "卡面未标注 tradition 字段，按题面体裁自决：大六壬（OC-028 课式重审/斫轮，三传辛卯玄武、丙戌朱雀、癸巳白虎，甲申旬午未空）。\n重审主事经复核而定、斫轮主雕琢成器，得官方向成；朱雀中传主文书考选、惜玄武初传主暗耗、白虎末传主职任辛劳，故品级压至中下——降格依据写明为初末传之象，合(b)。盘面不全守第八节。", 0.55)
P["OC-029"] = ("携子求官此行半成：子辈求官有小成/得面见机会而大位难成，本人此行耗费多收获少；家中高龄老母当年有病厄之关须防（应期年档，1642年冬至1643年内）。诸事总断：小吉大费、母事为重。", "卡面未标注 tradition 字段，按题面体裁自决：大六壬（OC-029 课式涉害/曲直/回环，三传乙未白虎、癸卯六合、己亥天后，甲午旬辰巳空，其子丑命）。\n曲直三合主求官有门路、六合中传主得人接引，故子事小成；初传白虎乘未土主道路耗费与长辈病象，母近九十、年命逢白虎为险据。回环格主往返重复、事难一举而成。盘面不全守第八节，应验对象逐项对回：子、本人、母三者分断，合(f)。", 0.52)
P["OC-030"] = ("两问皆难如愿：淮扬巡按差难复设（即复亦非旧制全复），吏书缺亦难照旧保留，总方向为两事俱落空/被改易。应期以月档：1651年当年内由上谕/部议定夺见分晓。", "卡面未标注 tradition 字段，按题面体裁自决：大六壬（OC-030 课式重审/铸印，三传癸巳太常、丙戌六合、辛卯太阴，月将亥将）。\n铸印格看似主印绶官职恢复，然三传巳戌卯火土相生而日干戊土受卯木官星克、太阴末传主暗中改易，旧制在易代之际被新局吞并；重审主反复议而终变。两问逐项同向落空，合事实优先(e)：废差复设在鼎革期本为逆势。盘面不全守第八节。", 0.55)
